package com.group01.assessment.application.usecase;
import com.group01.assessment.application.command.SaveAttemptResponseCommand; import com.group01.assessment.domain.entity.AttemptResponse;
import com.group01.assessment.domain.exception.*; import com.group01.assessment.domain.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.Instant; import java.util.UUID;
@Service public class SaveAttemptResponseUseCase {
 private final AssessmentAttemptRepository attempts; private final AttemptItemRepository items; private final AttemptResponseRepository responses;
 public SaveAttemptResponseUseCase(AssessmentAttemptRepository attempts,AttemptItemRepository items,AttemptResponseRepository responses){this.attempts=attempts;this.items=items;this.responses=responses;}
 @Transactional public AttemptResponse execute(SaveAttemptResponseCommand c){var a=attempts.findByIdAndUserId(c.attemptId(),c.userId()).orElseThrow(()->new AssessmentNotFoundException("Assessment attempt not found")); if(a.getStatus()!=com.group01.assessment.domain.vo.AttemptStatus.IN_PROGRESS) throw new InvalidAssessmentStateException("Only in-progress attempts accept responses"); items.findByIdAndAttemptId(c.itemId(),c.attemptId()).orElseThrow(()->new AssessmentNotFoundException("Attempt item not found")); var old=responses.findByAttemptItemId(c.itemId()); long current=old.map(AttemptResponse::revision).orElse(0L); if(current!=c.expectedRevision()) throw new RevisionConflictException("Response revision conflict"); var value=new AttemptResponse(old.map(AttemptResponse::id).orElse(UUID.randomUUID()),c.itemId(),c.payload(),c.schemaVersion(),current+1,Instant.now(),null,old.map(AttemptResponse::lockVersion).orElse(0L)); return responses.save(value);}
}
